#include <bits/stdc++.h>
using namespace std;
class ArrayStack{vector<int>a;int cap;public:explicit ArrayStack(int c=-1):cap(c){}void push(int x){if(cap>=0&&(int)a.size()>=cap)throw overflow_error("Stack overflow");a.push_back(x);}int pop(){if(a.empty())throw underflow_error("Stack empty");int x=a.back();a.pop_back();return x;}int peek()const{if(a.empty())throw underflow_error("Stack empty");return a.back();}bool empty()const{return a.empty();}size_t size()const{return a.size();}void clear(){a.clear();}};
class LinkedStack{struct Node{int v;Node*n;Node(int x,Node*y):v(x),n(y){}};Node*t=nullptr;size_t n=0;public:~LinkedStack(){while(t){Node*x=t;t=t->n;delete x;}}void push(int x){t=new Node(x,t);++n;}int pop(){if(!t)throw underflow_error("Stack empty");Node*x=t;int v=x->v;t=t->n;delete x;--n;return v;}int peek()const{if(!t)throw underflow_error("Stack empty");return t->v;}bool empty()const{return !t;}size_t size()const{return n;}};
class MinStack{stack<int>s,m;public:void push(int x){s.push(x);m.push(m.empty()?x:min(x,m.top()));}void pop(){if(s.empty())throw underflow_error("Stack empty");s.pop();m.pop();}int top()const{if(s.empty())throw underflow_error("Stack empty");return s.top();}int getMin()const{if(m.empty())throw underflow_error("Stack empty");return m.top();}};
// Encoding trick: use long long to avoid intermediate overflow for ordinary int inputs.
class MinStackEncoded{stack<long long>s;long long mn=0;public:void push(long long x){if(s.empty())mn=x,s.push(x);else if(x>=mn)s.push(x);else{s.push(2*x-mn);mn=x;}}void pop(){if(s.empty())throw underflow_error("Stack empty");long long x=s.top();s.pop();if(x<mn)mn=2*mn-x;if(s.empty())mn=0;}long long top()const{if(s.empty())throw underflow_error("Stack empty");long long x=s.top();return x<mn?mn:x;}long long getMin()const{if(s.empty())throw underflow_error("Stack empty");return mn;}};
bool validParentheses(const string&s){stack<char>st;for(char c:s){if(c=='('||c=='['||c=='{')st.push(c);else if(c==')'||c==']'||c=='}'){if(st.empty())return false;char t=st.top();st.pop();if((c==')'&&t!='(')||(c==']'&&t!='[')||(c=='}'&&t!='{'))return false;}}return st.empty();}
string removeAdjacentDuplicates(string s){string st;for(char c:s){if(!st.empty()&&st.back()==c)st.pop_back();else st.push_back(c);}return st;}
string removeDuplicatesK(string s,int k){if(k<=1)return "";vector<pair<char,int>>st;for(char c:s){if(!st.empty()&&st.back().first==c)++st.back().second;else st.push_back({c,1});if(st.back().second==k)st.pop_back();}string r;for(auto [c,n]:st)r.append(n,c);return r;}
vector<int> nextGreater(const vector<int>&a){vector<int>r(a.size(),-1),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]<a[i])r[st.back()]=a[i],st.pop_back();st.push_back(i);}return r;}
vector<int> nextGreaterCircular(const vector<int>&a){int n=a.size();vector<int>r(n,-1),st;for(int i=0;i<2*n;++i){int j=i%n;while(!st.empty()&&a[st.back()]<a[j])r[st.back()]=a[j],st.pop_back();if(i<n)st.push_back(j);}return r;}
vector<int> nextSmaller(const vector<int>&a){vector<int>r(a.size(),-1),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]>a[i])r[st.back()]=a[i],st.pop_back();st.push_back(i);}return r;}
vector<int> previousGreater(const vector<int>&a){vector<int>r(a.size(),-1),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]<=a[i])st.pop_back();if(!st.empty())r[i]=a[st.back()];st.push_back(i);}return r;}
vector<int> previousSmaller(const vector<int>&a){vector<int>r(a.size(),-1),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]>=a[i])st.pop_back();if(!st.empty())r[i]=a[st.back()];st.push_back(i);}return r;}
vector<int> dailyTemperatures(const vector<int>&a){vector<int>r(a.size()),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]<a[i]){int j=st.back();st.pop_back();r[j]=i-j;}st.push_back(i);}return r;}
vector<int> stockSpan(const vector<int>&a){vector<int>r(a.size()),st;for(int i=0;i<(int)a.size();++i){while(!st.empty()&&a[st.back()]<=a[i])st.pop_back();r[i]=st.empty()?i+1:i-st.back();st.push_back(i);}return r;}
long long largestRectangle(vector<int>h){h.push_back(0);vector<int>st;long long best=0;for(int i=0;i<(int)h.size();++i){while(!st.empty()&&h[st.back()]>h[i]){int height=h[st.back()];st.pop_back();int left=st.empty()?-1:st.back();best=max(best,1LL*height*(i-left-1));}st.push_back(i);}return best;}
int maximalRectangle(const vector<vector<char>>&m){if(m.empty())return 0;vector<int>h(m[0].size());long long ans=0;for(auto&r:m){for(int j=0;j<(int)h.size();++j)h[j]=(r[j]=='1')?h[j]+1:0;ans=max(ans,largestRectangle(h));}return (int)ans;}
int evalRPN(const vector<string>&t){stack<long long>s;for(auto&x:t){if(x!="+"&&x!="-"&&x!="*"&&x!="/"){s.push(stoll(x));continue;}if(s.size()<2)throw invalid_argument("Malformed RPN");long long b=s.top();s.pop();long long a=s.top();s.pop();if(x=="+")s.push(a+b);else if(x=="-")s.push(a-b);else if(x=="*")s.push(a*b);else s.push(a/b);}if(s.size()!=1)throw invalid_argument("Malformed RPN");return (int)s.top();}
int calculateBasicII(const string&s){stack<long long>st;long long num=0;char sign='+';for(size_t i=0;i<=s.size();++i){char c=i==s.size()?'+':s[i];if(isdigit((unsigned char)c))num=num*10+c-'0';else if(c==' ')continue;else{if(sign=='+')st.push(num);else if(sign=='-')st.push(-num);else if(sign=='*'){long long x=st.top();st.pop();st.push(x*num);}else if(sign=='/'){long long x=st.top();st.pop();st.push(x/num);}sign=c;num=0;}}long long ans=0;while(!st.empty())ans+=st.top(),st.pop();return (int)ans;}
int calculateBasic(const string&s){long long res=0,num=0;int sign=1;stack<pair<long long,int>>st;for(char c:s){if(isdigit((unsigned char)c))num=num*10+c-'0';else if(c=='+'||c=='-'){res+=sign*num;num=0;sign=c=='+'?1:-1;}else if(c=='('){st.push({res,sign});res=0;sign=1;}else if(c==')'){res+=sign*num;num=0;auto [prev,sgn]=st.top();st.pop();res=prev+sgn*res;}}return (int)(res+sign*num);}
int precedence(char c){if(c=='+'||c=='-')return 1;if(c=='*'||c=='/')return 2;if(c=='^')return 3;return 0;}
string infixToPostfix(const string&e){string out;stack<char>st;for(char c:e){if(isalnum((unsigned char)c))out+=c;else if(c=='(')st.push(c);else if(c==')'){while(!st.empty()&&st.top()!='(')out+=st.top(),st.pop();if(!st.empty())st.pop();}else if(c==' ' )continue;else{while(!st.empty()&&st.top()!='('&&(precedence(st.top())>precedence(c)||(precedence(st.top())==precedence(c)&&c!='^')))out+=st.top(),st.pop();st.push(c);}}while(!st.empty())out+=st.top(),st.pop();return out;}
string infixToPrefix(const string&e){string r=e;reverse(r.begin(),r.end());for(char&c:r)if(c=='(')c=')';else if(c==')')c='(';string p=infixToPostfix(r);reverse(p.begin(),p.end());return p;}
long long evalPostfix(const string&e){istringstream in(e);string t;stack<long long>s;while(in>>t){if(t.size()>1&&t[0]=='-'||isdigit((unsigned char)t[0]))s.push(stoll(t));else{long long b=s.top();s.pop();long long a=s.top();s.pop();if(t=="+")s.push(a+b);else if(t=="-")s.push(a-b);else if(t=="*")s.push(a*b);else s.push(a/b);}}return s.top();}
long long evalPrefix(const string&e){istringstream in(e);vector<string>v;string t;while(in>>t)v.push_back(t);stack<long long>s;for(auto it=v.rbegin();it!=v.rend();++it){t=*it;if(t.size()>1&&t[0]=='-'||isdigit((unsigned char)t[0]))s.push(stoll(t));else{long long a=s.top();s.pop();long long b=s.top();s.pop();if(t=="+")s.push(a+b);else if(t=="-")s.push(a-b);else if(t=="*")s.push(a*b);else s.push(a/b);}}return s.top();}
string simplifyPath(const string&p){vector<string>s;stringstream ss(p);string x;while(getline(ss,x,'/')){if(x.empty()||x==".")continue;if(x==".."){if(!s.empty())s.pop_back();}else s.push_back(x);}string r="/";for(int i=0;i<(int)s.size();++i){if(i)r+='/';r+=s[i];}return r;}
string decodeString(const string&s){stack<int>counts;stack<string>parts;string cur;int n=0;for(char c:s){if(isdigit((unsigned char)c))n=n*10+c-'0';else if(c=='['){counts.push(n);parts.push(cur);cur.clear();n=0;}else if(c==']'){int k=counts.top();counts.pop();string prev=parts.top();parts.pop();while(k--)prev+=cur;cur=prev;}else cur+=c;}return cur;}
vector<int> asteroidCollision(const vector<int>&a){vector<int>s;for(int x:a){bool alive=true;while(alive&&x<0&&!s.empty()&&s.back()>0){if(s.back()<-x)s.pop_back();else if(s.back()==-x)s.pop_back(),alive=false;else alive=false;}if(alive)s.push_back(x);}return s;}
string removeKdigits(string num,int k){string s;for(char c:num){while(k>0&&!s.empty()&&s.back()>c)s.pop_back(),--k;s.push_back(c);}while(k-->0&&!s.empty())s.pop_back();size_t i=s.find_first_not_of('0');return i==string::npos?"0":s.substr(i);}
int trapRainWater(const vector<int>&h){int n=h.size(),ans=0;vector<int>s;for(int i=0;i<n;++i){while(!s.empty()&&h[i]>h[s.back()]){int mid=s.back();s.pop_back();if(s.empty())break;ans+=(min(h[i],h[s.back()])-h[mid])*(i-s.back()-1);}s.push_back(i);}return ans;}
class StockSpanner{stack<pair<int,int>>s;public:int next(int p){int span=1;while(!s.empty()&&s.top().first<=p)span+=s.top().second,s.pop();s.push({p,span});return span;}};
class QueueUsingStacks{stack<int>a,b;void move(){if(b.empty())while(!a.empty())b.push(a.top()),a.pop();}public:void push(int x){a.push(x);}int pop(){move();if(b.empty())throw underflow_error("Queue empty");int x=b.top();b.pop();return x;}int peek(){move();if(b.empty())throw underflow_error("Queue empty");return b.top();}bool empty()const{return a.empty()&&b.empty();}};
class StackUsingQueues{queue<int>q;public:void push(int x){q.push(x);for(size_t i=1;i<q.size();++i)q.push(q.front()),q.pop();}int pop(){if(q.empty())throw underflow_error("Stack empty");int x=q.front();q.pop();return x;}int top()const{if(q.empty())throw underflow_error("Stack empty");return q.front();}};
void sortStack(stack<int>&s){stack<int>t;while(!s.empty()){int x=s.top();s.pop();while(!t.empty()&&t.top()>x)s.push(t.top()),t.pop();t.push(x);}while(!t.empty())s.push(t.top()),t.pop();}
void insertAtBottom(stack<int>&s,int x){if(s.empty()){s.push(x);return;}int t=s.top();s.pop();insertAtBottom(s,x);s.push(t);}void reverseStackRecursive(stack<int>&s){if(s.empty())return;int x=s.top();s.pop();reverseStackRecursive(s);insertAtBottom(s,x);}
void deleteMiddleStack(stack<int>&s){if(s.empty())return;stack<int>t;int mid=s.size()/2;for(int i=0;i<mid;++i)t.push(s.top()),s.pop();s.pop();while(!t.empty())s.push(t.top()),t.pop();}
int celebrity(const vector<vector<int>>&m){int n=m.size();if(!n)return -1;int a=0,b=n-1;while(a<b){if(m[a][b])++a;else --b;}for(int i=0;i<n;++i)if(i!=a&&(m[a][i]||!m[i][a]))return -1;return a;}
vector<int> dfsIterative(const vector<vector<int>>&g,int s){vector<int>v(g.size()),o;stack<int>st;st.push(s);while(!st.empty()){int u=st.top();st.pop();if(v[u])continue;v[u]=1;o.push_back(u);for(auto it=g[u].rbegin();it!=g[u].rend();++it)if(!v[*it])st.push(*it);}return o;}
vector<vector<int>> subsetsIterative(const vector<int>&a){vector<vector<int>>r{{}};for(int x:a){int n=r.size();for(int i=0;i<n;++i){auto t=r[i];t.push_back(x);r.push_back(move(t));}}return r;}
vector<string> generateBinaryQueue(int n){vector<string>r;if(n<=0)return r;queue<string>q;q.push("1");while(n--){string x=q.front();q.pop();r.push_back(x);q.push(x+"0");q.push(x+"1");}return r;}
class BrowserHistory{vector<string>back,forward;string cur;public:explicit BrowserHistory(string h):cur(move(h)){}void visit(string u){back.push_back(cur);cur=move(u);forward.clear();}string goBack(){if(back.empty())return cur;forward.push_back(cur);cur=back.back();back.pop_back();return cur;}string goForward(){if(forward.empty())return cur;back.push_back(cur);cur=forward.back();forward.pop_back();return cur;}};
vector<int> nextGreaterDistance(const vector<int>&a){vector<int>r(a.size());stack<int>s;for(int i=0;i<(int)a.size();++i){while(!s.empty()&&a[s.top()]<a[i]){int j=s.top();s.pop();r[j]=i-j;}s.push(i);}return r;}
